# Generate all non-zero vectors in F_3^3
vectors = []
for x in range(3):
    for y in range(3):
        for z in range(3):
            if (x,y,z) != (0,0,0):
                vectors.append((x,y,z))

# Group into equivalence classes under scalar multiplication by 2 (mod 3)
classes = []
used = set()
for v in vectors:
    if v in used:
        continue
    v2 = tuple((2*coord) % 3 for coord in v)
    cls = {v, v2}
    classes.append(cls)
    used.update(cls)

# Representatives
reps = []
for cls in classes:
    rep = min(cls)
    reps.append(rep)

reps = sorted(reps)

# Points and lines are both these 13 reps
points = reps
lines = reps

# Build incidence graph edges
edges = []
for i, p in enumerate(points):
    for j, l in enumerate(lines):
        dot = (p[0]*l[0] + p[1]*l[1] + p[2]*l[2]) % 3
        if dot == 0:
            edges.append((i, 13+j))

